import{_ as r,o,c as t,ag as a}from"./chunks/framework.cyF4XceO.js";const f=JSON.parse('{"title":"Takoform Provider を使う","description":"","frontmatter":{},"headers":[],"relativePath":"ja/docs/index.md","filePath":"ja/docs/index.md"}'),s={name:"ja/docs/index.md"};function d(i,e,c,n,h,m){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="takoform-provider-を使う" tabindex="-1">Takoform Provider を使う <a class="header-anchor" href="#takoform-provider-を使う" aria-label="Permalink to &quot;Takoform Provider を使う&quot;">​</a></h1><p>Terraform / OpenTofu の HCL から、互換 Host が公開する exact Form を管理します。 Host の接続先、Space、認証情報、サービスの実装は選択した Host が提供します。</p><h2 id="利用する版を選ぶ" tabindex="-1">利用する版を選ぶ <a class="header-anchor" href="#利用する版を選ぶ" aria-label="Permalink to &quot;利用する版を選ぶ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用途</th><th>Provider</th><th>Host API</th><th>対応する resource</th></tr></thead><tbody><tr><td>現行の source target / candidate</td><td><strong>5.0.0</strong></td><td><code>forms.takoform.com/v2</code></td><td>exact Edge Form URL 13 種</td></tr><tr><td>非推奨の Registry 公開版</td><td><strong>4.1.0</strong></td><td><code>forms.takoform.com/v1</code></td><td>Edge Form 17 種</td></tr></tbody></table><p>通常の source build で使う Provider は Host API v2 です。v1 client は非推奨で、default entrypoint ではサポートされません。4.1.0 の Registry 公開は <a href="https://github.com/tako0614/terraform-provider-takoform/blob/main/release/provider-release-identities.json" target="_blank" rel="noreferrer">release identity ledger</a> に記録されています。Provider 5.0.0 は source target で、Registry 公開済みとは確認されていません。 インストール前に公開一覧と exact version の readback を確認してください。 <strong>Provider 4 の state は Provider 5 へ自動変換されません。</strong></p><h2 id="現行の-source-path-provider-5-を評価する" tabindex="-1">現行の source path: Provider 5 を評価する <a class="header-anchor" href="#現行の-source-path-provider-5-を評価する" aria-label="Permalink to &quot;現行の source path: Provider 5 を評価する&quot;">​</a></h2><p><a href="/docs/provider-host-api-v2-source.html">Provider 5 consumer reference（英語）</a>に、現行の v2 schema、 13 種の対応表、local / remote private-store の設定、import、lifecycle の境界をまとめています。 Host は <code>forms.takoform.com/v2</code> と exact Form URL に独立して対応している必要があります。</p><h2 id="非推奨の-registry-公開版-provider-4-1-0" tabindex="-1">非推奨の Registry 公開版 Provider 4.1.0 <a class="header-anchor" href="#非推奨の-registry-公開版-provider-4-1-0" aria-label="Permalink to &quot;非推奨の Registry 公開版 Provider 4.1.0&quot;">​</a></h2><p><a href="/ja/docs/getting-started.html">旧版の入門ガイド</a>は、既存 workspace 向けの Registry 公開済み Provider 4.1.0 / Host API v1 を説明します。この release は default Provider 5 entrypoint では サポートされません。</p><h2 id="resource-reference" tabindex="-1">Resource reference <a class="header-anchor" href="#resource-reference" aria-label="Permalink to &quot;Resource reference {#resource-reference}&quot;">​</a></h2><p><a href="/docs/reference.html#resource-reference">Provider reference（英語）</a>と 17 種の個別ページは 非推奨の <strong>Provider 4.1.0 / Host API v1</strong> の説明です。現行の source-v2 schema と Form URL は 上記の Provider 5 reference を参照してください。</p><p>更新前には<a href="/ja/docs/versions.html">バージョンと互換性</a>と <a href="/release/migrations/v3-to-v4.html">v3-to-v4 migration（英語）</a>を確認してください。 実行可能な検証は<a href="/conformance/">Conformance（英語）</a>、provider-neutral な契約は <a href="https://takoform.com/host-api/" target="_blank" rel="noreferrer">Host API ドキュメント</a>にあります。</p><p>Host 設定と resource 宣言はガイドにあります。AWS resource と組み合わせる場合は <a href="/examples/native-provider-composition/main.tf">native provider composition</a> を参照してください。 各 Provider の source、認証情報、state は独立しています。</p>',13)])])}const p=r(s,[["render",d]]);export{f as __pageData,p as default};
